```json
[
  {
    "name": "Kobe Beef Steak Mouriya Gion",
    "summary": "Kobe Beef Steak Mouriya Gion offers a classy teppanyaki experience with high-quality Kobe filet. While some found it slightly basic for the price, most praise the excellent service, atmosphere, and the unforgettable taste of the A5 Kobe Beef."
  },
  {
    "name": "Honolu Grande Kyoto Halal Restaurant",
    "summary": "Honolu Grande offers a unique Halal ramen experience with a spicy chicken-based broth that is both rich and creamy. Guests have praised the food and the reasonable prices, but some have noted issues with customer service and steep stairs."
  },
  {
    "name": "A5 Wagyu Sukiyaki Kyoto Panga Halal Restaurant",
    "summary": "A5 Wagyu Sukiyaki Kyoto Panga Halal Restaurant provides an exceptional dining experience, especially for Muslim travelers, with delicious A5 Wagyu sukiyaki prepared with care. The friendly, multilingual staff and traditional Japanese setting add to the unforgettable meal."
  },
  {
    "name": "Gyukatsu Kyoto Katsugyu",
    "summary": "Gyukatsu Kyoto Katsugyu serves delicious and reasonably priced beef sets in an upmarket yet accessible atmosphere. Customers rave about the tender, medium-rare beef, the option to cook it further on a mini stove, and the friendly, English-speaking staff."
  },
  {
    "name": "Nakashimaya",
    "summary": "Nakashimaya is a cozy and welcoming small restaurant serving delicious, authentic Kyoto cuisine. Visitors appreciate the friendly service, the perfectly presented dishes, and the overall delightful culinary experience."
  },
  {
    "name": "KYOTO ENGINE RAMEN",
    "summary": "KYOTO ENGINE RAMEN offers tasty ramen with unique flavor additions like chili gin and kelp vinegar, creating a memorable twist. Known for its excellent service, the restaurant also provides gluten-free and vegan options, making it suitable for various dietary needs."
  },
  {
    "name": "Kyoto Dining",
    "summary": "Kyoto Dining offers a taste of home with its delicious and perfectly spiced Nepali and Indian cuisine, with generous portions. The friendly staff and warm atmosphere make it a must-visit for those seeking flavorful food and a welcoming experience."
  },
  {
    "name": "Itoh Dining",
    "summary": "Itoh Dining provides a fine dining experience with a focus on Kobe and Wagyu beef, served in a romantic atmosphere. While some find it slightly lacking in authentic Japanese cuisine, the accommodating staff, fast service, and stunning location make it a worthwhile visit."
  },
  {
    "name": "Wakana",
    "summary": "Wakana offers a peaceful escape with local specialties like beef sets and Hojicha shaved ice. Visitors enjoy the unique bowls with different sauces and a chance to taste various flavors of dango in a small, cozy setting."
  },
  {
    "name": "Fortune Garden Kyoto",
    "summary": "Fortune Garden Kyoto provides a fine dining experience with delicious food, particularly the fried onion soup and fish dishes. However, some diners have noted issues with the loud music, dim lighting, slow service, and a few unusual presentation choices that detract from the overall ambiance."
  }
]
```
